      Surface account=new Surface{Height=318,Padding=new Padding(22,16,22,16),Margin=new Padding(0,0,0,12)};TableLayoutPanel accountGrid=Design.Stack(4);accountGrid.BackColor=Design.Paper;accountGrid.RowStyles.Add(new RowStyle(SizeType.Absolute,35));for(int i=0;i<3;i++)accountGrid.RowStyles.Add(new RowStyle(SizeType.Percent,33.33f));Label section=Design.Heading("模型连接",11);section.Dock=DockStyle.Fill;accountGrid.Controls.Add(section,0,0);providers.DropDownStyle=ComboBoxStyle.DropDownList;providers.Items.AddRange(ProviderPreset.All);protocol.DropDownStyle=ComboBoxStyle.DropDownList;protocol.Items.AddRange(new object[]{"openai","anthropic","gemini"});key.UseSystemPasswordChar=true;
