th.Max(0,promptSurface.Top-content.AutoScrollPosition.Y));}));}};
      SoftButton advancedButton=new SoftButton{Text="高级连接设置  ⌄",Tone="quiet",Height=40,Width=180,Margin=new Padding(0,0,0,10)};content.Controls.Add(advancedButton);
