      chars.Minimum=2000;chars.Maximum=80000;chars.Increment=2000;pages.Minimum=1;pages.Maximum=50;TableLayoutPanel limits=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,BackColor=Design.Paper};limits.Margin=Padding.Empty;limits.RowStyles.Add(new RowStyle(SizeType.Percent,100));limits.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));limits.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));Panel charsBlock=Block("最多发送字符",chars),pagesBlock=Block("最多提取页数",pages);charsBlock.Padding=new Padding(0,0,12,0);limits.Controls.Add(charsBlock,0,0);limits.Controls.Add(pagesBlock,1,0);advancedGrid.Controls.Add(limits,0,2);json.Text="启用 JSON 模式（模型支持时）";json.Dock=DockStyle.Fill;advancedGrid.Controls.Add(json,0,3);advanced.Controls.Add(advancedGrid);content.Controls.Add(advanced);
      Surface note=new Surface{Height=120,FillColor=Color.FromArgb(236,242,252),Padding=new Padding(20,14,20,14),Margin=new Padding(0,0,0,14)};Label noteText=Design.Label("设置会按服务商分别保存，切换时不必重填。\r\n只有点击“API 分析所选”才发送提取文本；保存设置不会调用 API。\r\n密钥在本机加密保存。模型名称和地域请以服务商控制台为准。",9,Design.Muted);noteText.Dock=DockStyle.Fill;note.Controls.Add(noteText);content.Controls.Add(note);
      Action resize=()=>{int width=Math.Max(200,content.ClientSize.Width-24);account.Width=advanced.Width=note.Width=promptSurface.Width=width;};content.Resize+=(s,e)=>resize();Shown+=(s,e)=>resize();advancedButton.Click+=(s,e)=>{advanced.Visible=!advanced.Visible;advancedButton.Text=advanced.Visible?"收起高级设置  ⌃":"高级连接设置  ⌄";resize();if(advanced.Visible){endpoint.Focus();BeginInvoke((Action)(()=>{if(IsDisposed)return;content.PerformLayout();content.AutoScrollPosition=new Point(0,Math.Max(0,advanced.Top-content.AutoScrollPosition.Y));}));}};
      TableLayoutPanel footer=Design.Stack(2);footer.RowStyles.Add(new RowStyle(SizeType.Absolute,34));footer.RowStyles.Add(new RowStyle(SizeType.Percent,100));status.Dock=DockStyle.Fill;status.AutoEllipsis=true;footer.Controls.Add(status,0,0);FlowLayoutPanel actions=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,WrapContents=false};SoftButton save=new SoftButton{Text="保存设置",Tone="primary",Width=130},cancel=new SoftButton{Text="取消",Tone="quiet",Width=78,DialogResult=DialogResult.Cancel},test=new SoftButton{Text="测试连接",Width=122};actions.Controls.AddRange(new Control[]{save,cancel,test});footer.Controls.Add(actions,0,1);root.Controls.Add(footer,0,2);CancelButton=cancel;
      providers.SelectedIndexChanged+=(s,e)=>SwitchProvider();save.Click+=(s,e)=>{try{CaptureProfile();config.Selected=current;store.Save(config);DialogResult=DialogResult.OK;Close();}catch(Exception error){status.ForeColor=Color.Firebrick;status.Text=error.Message;}};
      test.Click+=async(s,e)=>{test.Enabled=false;try{CaptureProfile();status.ForeColor=Design.Muted;status.Text="正在测试连接…";await new AiClient().Test(config.Profile(current));status.ForeColor=Color.FromArgb(25,134,95);status.Text="连接成功，当前模型已返回响应。";}catch(Exception error){status.ForeColor=Color.Firebrick;status.Text=error.Message;}finally{if(!IsDisposed)test.Enabled=true;}};
      providers.SelectedItem=ProviderPreset.All.FirstOrDefault(p=>p.Id==config.Selected)??ProviderPreset.All[0];
