    static Panel Block(string text,Control control){Panel block=new Panel{Dock=DockStyle.Fill,BackColor=Design.Paper,Margin=Padding.Empty,Padding=new Padding(0,0,0,9)};Label label=Design.Label(text,9,Design.Muted);label.Dock=DockStyle.Top;label.Height=25;Surface field=Design.Field(control,false);block.Controls.Add(field);block.Controls.Add(label);return block;}
    static string PromptForDisplay(string value){return value.Replace("\r\n","\n").Replace("\n","\r\n");}
    void CaptureProfile(){if(current==null)return;ApiProfile p=config.Profile(current);p.Protocol=Convert.ToString(protocol.SelectedItem);p.Endpoint=endpoint.Text.Trim();p.Model=model.Text.Trim();p.EncryptedKey=AiSettingsStore.Encrypt(key.Text.Trim());p.JsonMode=json.Checked;p.MaxCharacters=(int)chars.Value;p.MaxPages=(int)pages.Value;string rules=classificationPrompt.Text.Replace("\r\n","\n").Trim();p.ClassificationPrompt=rules==AiClient.DefaultClassificationPrompt?"":rules;}
    void SwitchProvider(){if(switching)return;switching=true;try{CaptureProfile();current=((ProviderPreset)providers.SelectedItem).Id;ApiProfile p=config.Profile(current);protocol.SelectedItem=p.Protocol;endpoint.Text=p.Endpoint;model.Text=p.Model;key.Text=AiSettingsStore.Decrypt(p.EncryptedKey);json.Checked=p.JsonMode;chars.Value=Math.Max(2000,Math.Min(80000,p.MaxCharacters));pages.Value=Math.Max(1,Math.Min(50,p.MaxPages));classificationPrompt.Text=PromptForDisplay(AiClient.EffectiveClassificationPrompt(p));status.Text="";}finally{switching=false;}}
